import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const credit =
  'Skeleton generated by ESPresso, a tool made by James Platt for Manchester Stinger Motorsports';
const puns = new Set([
  'This code tastes like coffee!',
  'May your coffee be strong and your latency low.',
  'Grounds for a great project.',
  'Brewed to run',
  'A latte tasks, only 1 chip',
  'Bean there, built that.',
  'A fresh pot of parallel problems',
  'Every task deserves a coffee break.',
  'This project has bean brewing.',
  'Bean busy making tasks.',
  'A little chip with a latte potential.',
  'Wake up and smell the semaphores (and coffee)',
]);
const call = (request) =>
  JSON.parse(
    execFileSync('build/native/Release/espresso-core.exe', [], {
      input: JSON.stringify(request),
      encoding: 'utf8',
      windowsHide: true,
      maxBuffer: 24 * 1024 * 1024,
    }),
  );
const request = (value) => {
  const response = call(value);
  assert.equal(response.ok, true, response.error);
  return response.result;
};
const project = () => ({
  version: 1,
  name: 'coffee-node',
  target: 'esp32s3',
  nodes: Array.from({ length: 24 }, (_, i) => ({
    id: randomUUID(),
    kind: 'task',
    name: `Task ${i}`,
    symbol: `worker${i}`,
    position: { x: i * 270, y: 0 },
    periodMs: 100,
    priority: 2,
    stackBytes: 4096,
    core: 'any',
    libraryIds: ['sensor'],
    setup: [],
    loop: [],
  })),
  libraries: [
    {
      id: 'sensor',
      name: 'Sensor',
      source: 'local',
      version: 'local',
      headers: ['Sensor.hpp'],
      dependencies: [],
      files: { 'Sensor.hpp': '#pragma once\n// Third-party library.\n' },
    },
  ],
});
const exportTo = (p) =>
  request({
    op: 'export',
    project: p,
    path: fs.mkdtempSync(path.join(os.tmpdir(), 'espresso-coffee-')),
  }).path;

test('generated files carry the credit, with stable coffee puns only on task sources', () => {
  const p = project();
  const first = request({ op: 'preview', project: p });
  assert.equal(first.valid, true);
  const seen = new Set();
  for (const [name, text] of Object.entries(first.files)) {
    if (name.startsWith('components/')) continue;
    if (name.endsWith('.json')) {
      assert.equal(JSON.parse(text).generatorCredit, credit, name);
      continue;
    }
    if (/^main\/tasks\/.*_task\.cpp$/.test(name)) {
      const [pun, attribution, separator] = text.split('\n');
      assert.ok(puns.has(pun.slice(2)), name);
      assert.equal(attribution, '//' + credit, name);
      assert.equal(separator, '', name);
      seen.add(pun);
    } else {
      const prefix = /\.(cpp|hpp|h)$/.test(name)
        ? '//' + credit
        : name.endsWith('.md')
          ? '<!--' + credit + '-->'
          : '#' + credit;
      assert.ok(text.startsWith(prefix + '\n\n'), name);
    }
  }
  assert.ok(seen.size > 1, 'Different random task IDs select different puns');
  assert.deepEqual(request({ op: 'preview', project: p }).files, first.files);
  assert.equal(
    first.files['components/Sensor/Sensor.hpp'],
    p.libraries[0].files['Sensor.hpp'],
  );
  const output = exportTo(p);
  const manifest = JSON.parse(
    fs.readFileSync(path.join(output, 'espresso.project.json'), 'utf8'),
  );
  assert.equal(manifest.generatorCredit, credit);
  for (const [name, text] of Object.entries(first.files))
    assert.equal(fs.readFileSync(path.join(output, name), 'utf8'), text, name);
  const sourceName = 'main/tasks/worker0_task.cpp';
  const handwritten =
    first.files[sourceName] + '\n// My board implementation.\n';
  fs.writeFileSync(path.join(output, sourceName), handwritten);
  const imported = request({
    op: 'import-project',
    path: path.join(output, 'espresso.project.json'),
  }).project;
  const second = exportTo(imported);
  assert.equal(
    fs.readFileSync(path.join(second, sourceName), 'utf8'),
    handwritten,
  );
  assert.equal(handwritten.split(credit).length - 1, 1);
});

test('edited generated code is rejected during import', () => {
  const p = project();
  p.nodes = p.nodes.slice(0, 1);
  const output = exportTo(p);
  fs.appendFileSync(
    path.join(output, 'main/generated/task_runtime.cpp'),
    '\nvoid unexpected_edit() {}\n',
  );
  const rejected = call({
    op: 'import-project',
    path: path.join(output, 'espresso.project.json'),
  });
  assert.equal(rejected.ok, false);
  assert.match(rejected.error, /generated file changed/);
});
